import{_ as i,C as E,o,c as s,a2 as r,b as A,w as n,a,E as d,a3 as c,j as t}from"./chunks/framework.RycU2wFZ.js";const B=JSON.parse('{"title":"树状组织多层配额模型与预算控制体系 (FinOps Quota Governance)","description":"","frontmatter":{},"headers":[],"relativePath":"finops/budget-control.md","filePath":"finops/budget-control.md"}'),g={name:"finops/budget-control.md"};function p(u,e,_,h,C,m){const l=E("Mermaid");return o(),s("div",null,[e[1]||(e[1]=r('<h1 id="树状组织多层配额模型与预算控制体系-finops-quota-governance" tabindex="-1">树状组织多层配额模型与预算控制体系 (FinOps Quota Governance) <a class="header-anchor" href="#树状组织多层配额模型与预算控制体系-finops-quota-governance" aria-label="Permalink to &quot;树状组织多层配额模型与预算控制体系 (FinOps Quota Governance)&quot;">​</a></h1><blockquote><p><strong>版本</strong>：v2.0.0<br><strong>适用范围</strong>：AgentFinOps 企业控制台、Go Gateway 策略执行引擎、PostgreSQL 存储域<br><strong>关联规划</strong>：Master Roadmap v2.0.0 模块二（2.1 树状组织多层配额体系）</p></blockquote><hr><h2 id="_1-业务痛点与架构愿景" tabindex="-1">1. 业务痛点与架构愿景 <a class="header-anchor" href="#_1-业务痛点与架构愿景" aria-label="Permalink to &quot;1. 业务痛点与架构愿景&quot;">​</a></h2><p>企业在规模化接入大模型与智能体时，面临极其突出的财务治理痛点：</p><ol><li><strong>费用一锅粥</strong>：所有项目与 Agent 共享同一个 API Key 或总账户，月末数十万开销无法核算到具体事业群或部门；</li><li><strong>死循环穿透风险</strong>：某一个边缘实验项目的 Agent 陷入死循环递归调用，导致整个企业总账户额度被瞬间刷爆，核心生产业务被迫瘫痪；</li><li><strong>缺乏级联审批与动态划拨</strong>：无法按季度或按月向下级业务线安全授权配额。</li></ol><p>AgentPay 提出<strong>四级成本切分与树状预算治理架构</strong>： $$\\text{企业租户 (Tenant)} \\longrightarrow \\text{事业群/部门 (Department)} \\longrightarrow \\text{项目组 (Project)} \\longrightarrow \\text{具体智能体 (Agent)}$$</p>',7)),(o(),A(c,null,{default:n(()=>[d(l,{id:"mermaid-35",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Tenant%5B%22%E4%BC%81%E4%B8%9A%E6%80%BB%E7%A7%9F%E6%88%B7%20(Tenant)%3Cbr%2F%3E%E8%B5%84%E9%87%91%E6%B1%A0%E4%BD%99%E9%A2%9D%3A%20100%2C000%20%E5%85%83%22%5D%0A%20%20%20%20%0A%20%20%20%20Tenant%20--%3E%20Dept1%5B%22%E7%A0%94%E5%8F%91%E4%BA%8B%E4%B8%9A%E7%BE%A4%20(Department%20A)%3Cbr%2F%3E%E6%9C%88%E5%BA%A6%E9%A2%84%E7%AE%97%E9%85%8D%E9%A2%9D%3A%2060%2C000%20%E5%85%83%22%5D%0A%20%20%20%20Tenant%20--%3E%20Dept2%5B%22%E5%B8%82%E5%9C%BA%E4%B8%8E%E8%BF%90%E8%90%A5%E9%83%A8%20(Department%20B)%3Cbr%2F%3E%E6%9C%88%E5%BA%A6%E9%A2%84%E7%AE%97%E9%85%8D%E9%A2%9D%3A%2040%2C000%20%E5%85%83%22%5D%0A%20%20%20%20%0A%20%20%20%20Dept1%20--%3E%20Proj1%5B%22AI%20%E7%BC%96%E7%A8%8B%E5%8A%A9%E6%89%8B%E9%A1%B9%E7%9B%AE%20(Project%201)%3Cbr%2F%3E%E6%9C%88%E5%BA%A6%E9%99%90%E9%A2%9D%3A%2040%2C000%20%E5%85%83%22%5D%0A%20%20%20%20Dept1%20--%3E%20Proj2%5B%22%E8%87%AA%E5%8A%A8%E5%8C%96%E6%B5%8B%E8%AF%95%E9%A1%B9%E7%9B%AE%20(Project%202)%3Cbr%2F%3E%E6%9C%88%E5%BA%A6%E9%99%90%E9%A2%9D%3A%2020%2C000%20%E5%85%83%22%5D%0A%20%20%20%20%0A%20%20%20%20Proj1%20--%3E%20Agent1%5B%22Coding%20Copilot%20(Agent%20A1)%3Cbr%2F%3E%E5%8D%95%E7%AC%94%E7%A1%AC%E9%A1%B6%3A%2050%20%E5%85%83%20%2F%20%E6%97%A5%E9%99%90%E9%A2%9D%3A%20500%20%E5%85%83%22%5D%0A%20%20%20%20Proj1%20--%3E%20Agent2%5B%22Code%20Reviewer%20(Agent%20A2)%3Cbr%2F%3E%E5%8D%95%E7%AC%94%E7%A1%AC%E9%A1%B6%3A%2020%20%E5%85%83%20%2F%20%E6%97%A5%E9%99%90%E9%A2%9D%3A%20200%20%E5%85%83%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t("hr",null,null,-1)),e[3]||(e[3]=t("h2",{id:"_2-级联预算约束公式与不变式-cascade-invariant",tabindex:"-1"},[a("2. 级联预算约束公式与不变式 (Cascade Invariant) "),t("a",{class:"header-anchor",href:"#_2-级联预算约束公式与不变式-cascade-invariant","aria-label":'Permalink to "2. 级联预算约束公式与不变式 (Cascade Invariant)"'},"​")],-1)),e[4]||(e[4]=t("p",null,[a("在 AgentPay 核心网关中，任何一笔外部请求的发起，必须在 $O(1)$ 时间内严格满足以下"),t("strong",null,"四层级联不变式（Cascade Invariant）"),a("：")],-1)),e[5]||(e[5]=t("p",null,[a("$$\\begin{cases} \\text{Agent.spent}"),t("em",{month:""},"{24h} + \\Delta \\le \\text{Agent.daily_budget_cap} & \\text{(Agent 层级限制)} \\ \\text{Project.spent}"),a(" + \\Delta \\le \\text{Project.monthly_budget_cap} & \\text{(项目组层级限制)} \\ \\text{Department.spent}_{month} + \\Delta \\le \\text{Department.monthly_budget_cap} & \\text{(部门层级限制)} \\ \\text{Tenant.available_balance} \\ge \\Delta & \\text{(租户总钱包余额)} \\end{cases}$$")],-1)),e[6]||(e[6]=r('<ul><li><strong>$\\Delta$（本次调用预估最大金额）</strong>：由路由标价或 Token 上限计算得出；</li><li><strong>若任何一层超限</strong>：网关毫秒级阻断，准确定位报错（如 <code>QUOTA_EXCEEDED_DEPARTMENT</code>），阻断信号立即通知负责人，同时同租户下其他部门与项目的调用完全不受影响。</li></ul><hr><h2 id="_3-预算模型生命周期" tabindex="-1">3. 预算模型生命周期 <a class="header-anchor" href="#_3-预算模型生命周期" aria-label="Permalink to &quot;3. 预算模型生命周期&quot;">​</a></h2><h3 id="_3-1-事前预算评估与冻结-pre-flight-hold" tabindex="-1">3.1 事前预算评估与冻结 (Pre-flight Hold) <a class="header-anchor" href="#_3-1-事前预算评估与冻结-pre-flight-hold" aria-label="Permalink to &quot;3.1 事前预算评估与冻结 (Pre-flight Hold)&quot;">​</a></h3><p>当 Agent 发起 HTTP 请求时：</p><ol><li>网关读取目标路由的单价或预估 Token 上限；</li><li>校验四级配额是否充足；</li><li>原子锁定配额：在虚拟钱包中执行 <code>Hold</code> 动作，扣减 <code>available_cache</code>，增加 <code>held_cache</code>。</li></ol><h3 id="_3-2-毫秒级流式计量-real-time-token-metering" tabindex="-1">3.2 毫秒级流式计量 (Real-time Token Metering) <a class="header-anchor" href="#_3-2-毫秒级流式计量-real-time-token-metering" aria-label="Permalink to &quot;3.2 毫秒级流式计量 (Real-time Token Metering)&quot;">​</a></h3><ol><li>网关反向代理至上游模型服务，流式解析 LLM 的 SSE 数据帧；</li><li>捕获最终的 <code>usage.prompt_tokens</code> 与 <code>usage.completion_tokens</code>；</li><li>计算本次实际应收金额 $\\text{ActualCost}$。</li></ol><h3 id="_3-3-事后确认扣除与释放-capture-release" tabindex="-1">3.3 事后确认扣除与释放 (Capture &amp; Release) <a class="header-anchor" href="#_3-3-事后确认扣除与释放-capture-release" aria-label="Permalink to &quot;3.3 事后确认扣除与释放 (Capture &amp; Release)&quot;">​</a></h3><ol><li><strong>确认扣费 (Capture)</strong>：将实际消耗金额 $\\text{ActualCost}$ 转化为不可变记账凭证（<code>ap_ledger_entry</code>）；</li><li><strong>释放剩余 (Release)</strong>：将多预留的额度 $(\\Delta - \\text{ActualCost})$ 即刻返还至可用额度；</li><li><strong>若调用失败/超时</strong>：将全部预留额度 $\\Delta$ 原子释放（<code>Release</code>），绝不产生悬挂扣款。</li></ol><hr><h2 id="_4-部门熔断机制与异动告警-circuit-breaker" tabindex="-1">4. 部门熔断机制与异动告警 (Circuit Breaker) <a class="header-anchor" href="#_4-部门熔断机制与异动告警-circuit-breaker" aria-label="Permalink to &quot;4. 部门熔断机制与异动告警 (Circuit Breaker)&quot;">​</a></h2><p>为防御智能体因为逻辑死循环（Runaway Agent Loop）导致成本失控，系统设置了两道防线：</p><ol><li><p><strong>瞬时 RPM 熔断器 (Sliding Window RPM Guard)</strong>：</p><ul><li>当单 Agent 或单项目的每分钟调用频次超过设定上限（如 60 RPM）时，策略引擎立即将熔断器状态由 <code>CLOSED</code> 切换为 <code>OPEN</code>；</li><li>所有后续请求在本地内存阶段直接拦截，返回 <code>429 RATE_LIMIT_EXCEEDED</code>。</li></ul></li><li><p><strong>自适应异动检测 (Anomaly Detection)</strong>：</p><ul><li>持续监控单 Agent 调用频次与金额偏离度；</li><li>首次异常触发企业微信/飞书/钉钉告警通知管理员；</li><li>持续异常自动降级 API Key 权限或移入隔离观察区。</li></ul></li></ol>',14))])}const b=i(g,[["render",p]]);export{B as __pageData,b as default};
